#define DLSS5_LAYER_BENCH 1
#include "hip_reference_network.h"
#include <cmath>
namespace hip_reference {struct LayerBenchmark {static bool Check(Network&n,U block,U post,bool crop){U w=crop?24:16,h=16,N=w*h,cw=crop?20:0,ch=crop?12:0,sx=crop?4:0,sy=sx;std::vector<float>fv(N*256);for(size_t i=0;i<fv.size();i++)fv[i]=float(int(i%17)-8)/8;std::vector<unsigned char>nv(N*768);for(size_t i=0;i<nv.size();i++)nv[i]=unsigned((i*37+i/31)%80)|((i%3==0)?128:0);auto f=n.Upload(fv.data(),fv.size()*4),q=n.Upload(nv.data(),nv.size()),av=n.New(N*256/4),a=n.New((crop?cw*ch:N)*256),b=n.New((crop?cw*ch:N)*256);auto weights=n.PackedMhWeight(n.Block(block,"attention"),256,true);
 n.Run("mh_fused","mh_attention_fused_fp8_out",size_t(N/64)*8,n.P(q),weights,n.P(av),w,h,U(256));
 if(crop)n.Run("mh_fast","mh_attention_crop",N*256,n.P(av),n.P(f),weights,n.P(a),N,post,cw,ch,w,sx,sy,U(256));else n.Run("mh_fast","mh_attention_project_fast_matrix_fp8",N*256,n.P(av),n.P(f),weights,n.P(a),N,U(256),post);
 n.Run("mh_fused","c256_attention_project",N/64,n.P(q),weights,n.P(f),n.P(b),w,h,post,cw,ch,sx,sy);n.Synchronize();std::vector<float>x((crop?cw*ch:N)*256),y(x.size());n.api.Check(n.api.hipMemcpy(x.data(),n.P(a),x.size()*4,2),"reference read");n.api.Check(n.api.hipMemcpy(y.data(),n.P(b),y.size()*4,2),"fused read");size_t diff=0,bad=0;for(size_t i=0;i<x.size();i++){diff+=memcmp(&x[i],&y[i],4)!=0;bad+=!std::isfinite(x[i])||!std::isfinite(y[i]);}printf("block=%u post=%u crop=%u bitdiff=%zu invalid=%zu\n",block,post,crop,diff,bad);return !diff&&!bad;}};}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("ASSETS MODULES required");hip_reference::Options o;o.assets=argv[1];o.modules=argv[2];o.mh_wave=o.fast_mh=o.fused_mh=o.packed_weights=o.fp8_av=o.fp8_normalized=true;hip_reference::Network n(o);bool ok=true;for(unsigned b:{15u,16u,17u,18u,19u,20u,21u,22u,48u,49u,50u,51u,52u,53u,54u,55u})for(unsigned post:{0u,3u,4u})for(bool crop:{false,true})ok=hip_reference::LayerBenchmark::Check(n,b,post,crop)&&ok;return ok?0:1;}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 2;}}
